-- Magento 2.4 tables the StoreOnCall plugin reads, generated from Magento's own etc/db_schema.xml files
-- (magento/magento2 commit 90f60c1e, November 2026; columns merged across modules). Table prefix placeholder: {{p}}
CREATE TABLE `{{p}}cron_schedule` (
  `schedule_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `job_code` VARCHAR(255) NOT NULL DEFAULT '0',
  `status` VARCHAR(7) NOT NULL DEFAULT 'pending',
  `messages` TEXT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `scheduled_at` TIMESTAMP NULL,
  `executed_at` TIMESTAMP NULL,
  `finished_at` TIMESTAMP NULL,
  PRIMARY KEY (`schedule_id`),
  KEY `CRON_SCHEDULE_JOB_CODE_STATUS_SCHEDULED_AT` (`job_code`,`status`,`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `{{p}}indexer_state` (
  `state_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `indexer_id` VARCHAR(255) NULL,
  `status` VARCHAR(16) NULL DEFAULT 'invalid',
  `updated` DATETIME NULL,
  `hash_config` VARCHAR(32) NOT NULL,
  PRIMARY KEY (`state_id`),
  KEY `INDEXER_STATE_INDEXER_ID` (`indexer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `{{p}}mview_state` (
  `state_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `view_id` VARCHAR(255) NULL,
  `mode` VARCHAR(16) NULL DEFAULT 'disabled',
  `status` VARCHAR(16) NULL DEFAULT 'idle',
  `updated` DATETIME NULL,
  `version_id` BIGINT UNSIGNED NULL,
  PRIMARY KEY (`state_id`),
  KEY `MVIEW_STATE_VIEW_ID` (`view_id`),
  KEY `MVIEW_STATE_MODE` (`mode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `{{p}}queue` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `QUEUE_NAME` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `{{p}}queue_message_status` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `queue_id` INT UNSIGNED NOT NULL,
  `message_id` BIGINT UNSIGNED NOT NULL,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status` SMALLINT UNSIGNED NOT NULL,
  `number_of_trials` SMALLINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `QUEUE_MESSAGE_STATUS_QUEUE_ID_MESSAGE_ID` (`queue_id`,`message_id`),
  KEY `QUEUE_MESSAGE_STATUS_STATUS_UPDATED_AT` (`status`,`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

